H.background();
const k = P.k;
const x = P.x * (0.5 + 0.5 * Math.sin(t * 0.9));
const F = k * x;
const PE = 0.5 * k * x * x;
const wallX = 80, restLen = 220, cy = 150;
const px = wallX + restLen + x * 20;
H.line(wallX, cy - 40, wallX, cy + 40, { color: H.colors.ink, width: 4 });
const coils = 12, pts = [];
for (let i = 0; i <= coils * 2; i++) {
  const fx = wallX + (px - 40 - wallX) * (i / (coils * 2));
  const fy = cy + ((i % 2 === 0) ? 0 : (i % 4 === 1 ? -16 : 16));
  pts.push([fx, fy]);
}
H.path(pts, { color: H.colors.accent, width: 3 });
H.rect(px - 40, cy - 26, 40, 52, { fill: H.colors.accent2, radius: 4 });
H.arrow(px - 20, cy, px - 20 - Math.max(8, F * 4), cy, { color: H.colors.warn, width: 3 });
const v = H.plot2d({ xMin: 0, xMax: 5, yMin: 0, yMax: 250 });
v.grid(); v.axes();
v.fn(s => 0.5 * k * s * s, { color: H.colors.good, width: 3 });
v.dot(Math.abs(x), PE, { r: 6, fill: H.colors.warn });
H.text("Hooke's law: F = k x,  PE = 1/2 k x^2", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Restoring force grows linearly; PE grows as x^2", 24, 52, { color: H.colors.sub, size: 13 });
H.text("x = " + x.toFixed(2) + " m   F = " + F.toFixed(1) + " N", 24, 78, { color: H.colors.sub, size: 13 });
H.text("PE = " + PE.toFixed(1) + " J", 24, 96, { color: H.colors.good, size: 13 });
